const doc = $json;
const content = doc?.body?.content || [];
let fullText = '';
for (const el of content) {
  const p = el.paragraph;
  if (!p?.elements) continue;
  for (const pe of p.elements) {
    const t = pe.textRun?.content;
    if (t) fullText += t;
  }
}
return [{ json: { docId: doc.documentId, fullText } }];

const results = $input.all();
const jobs = [];
const seen = new Set();

function stripHtml(html) {
  if (!html) return '';
  return html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/?(li|p|div|h[1-6])[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

for (const item of results) {
  const j = item.json;
  const jobLink = j.link || j.jobUrl || j.url || '';
  if (seen.has(jobLink) || !jobLink) continue;

  const postedAt = j.postedAt || '';
  const sevenDaysAgo = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
  if (postedAt < sevenDaysAgo) continue;

  const jobDescription = j.descriptionHtml
    ? stripHtml(j.descriptionHtml)
    : (j.descriptionText || '');
  if (!jobDescription || jobDescription.length < 50) continue;

  jobs.push({
    title:          j.title          || 'No Title',
    company:        j.companyName    || 'Unknown Company',
    location:       j.location       || 'Unknown Location',
    postedAt,
    employmentType: j.employmentType || '',
    seniorityLevel: j.seniorityLevel || '',
    jobLink,
    jobDescription
  });

  seen.add(jobLink);
  if (jobs.length >= 20) break;
}

return jobs.map(job => ({ json: job }));

const allJobs = $('Limit to 9 Jobs').all();
const config = $('Config: Keys & Search Params').first().json;
const supabaseUrl = config.supabaseUrl;
const supabaseKey = config.supabaseKey;
const existingUrls = new Set();
async function checkJobExists(jobUrl) {
  try {
    const response = await fetch(`${supabaseUrl}/rest/v1/jobs?job_url=eq.${encodeURIComponent(jobUrl)}&select=job_url`, { method: 'GET', headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}`, 'Content-Type': 'application/json' } });
    if (!response.ok) return null;
    const data = await response.json();
    return data.length > 0 ? jobUrl : null;
  } catch (error) { return null; }
}
const checkPromises = allJobs.map(job => checkJobExists(job.json.jobLink));
const results = await Promise.all(checkPromises);
for (const url of results) { if (url) existingUrls.add(url); }
const newJobs = allJobs.filter(job => !existingUrls.has(job.json.jobLink));
return newJobs;

